            $"--datrix-run healthcheck requires {HealthcheckUrlFlag} <url> " +
            "(the aspnet runtime image ships neither wget nor curl -- this " +
            "self-probe is the container HEALTHCHECK command).");
        return 1;
    }
    var url = args[urlIndex + 1];
    using var client = new HttpClient { Timeout = TimeSpan.FromSeconds(5) };
    try
    {
        var response = await client.GetAsync(url);
        return response.IsSuccessStatusCode ? 0 : 1;
    }
    catch (Exception ex)
    {
        Console.Error.WriteLine($"Healthcheck probe to {url} failed: {ex.Message}");
        return 1;
    }
}


