// Minimal, Kestrel-free DI container for one-shot migrate / seed / job /
// readiness CLI invocations. The guard above must cover EVERY caller of this
// helper, not just the migrate/seed pair it was first written for: the
// one-shot job dispatch (`RunOneShotJobAsync`, guarded by `has_jobs or
// has_container_scheduler_jobs`) and `RunReadinessAsync` (guarded by
// `has_runtime_readiness`) also call it, so a service whose only feature
// needing this provider is the readiness surface -- no rdbms block, no seed,
// no jobs -- emitted the call while this definition was guarded out, which is
// CS0103 at build time.
// Host.CreateApplicationBuilder() builds the SAME
// configuration sources (appsettings.json + environment variables) as
// WebApplication.CreateBuilder() without ever binding a socket, so these
// one-shot commands never open the service's HTTP port. Scoped to just the
// persistence/seed services this dispatch needs -- never AddControllers/
// AddOpenApi/CORS/health-check registrations, which belong to the web host
// path only.
static IServiceProvider BuildRuntimeServiceProvider()
{
    var builder = Host.CreateApplicationBuilder();
    // Same zero-env config sources as the web host (see WebApplication.CreateBuilder
    // above) so one-shot migrate/seed commands resolve the SAME database
    // connection from the config-store + /run/secrets, not a bare localhost.
    builder.Configuration.AddJsonFile("/app/config/config-store.json", optional: true, reloadOnChange: false);
    if (Directory.Exists("/run/secrets"))
    {
        builder.Configuration.AddKeyPerFile("/run/secrets", optional: true);
    }
    builder.Services.AddDbContext<BookServiceDbContext>(options =>
    options.UseNpgsql(BookDbConnectionOptions.BuildConnectionString(builder.Configuration))
        .AddInterceptors(new BookDbQueryDurationInterceptor()));
    builder.Services.AddFluentMigratorCore()
        .ConfigureRunner(rb =>
        {
            // FluentMigrator discovers this service's [Migration] classes by
            // ASSEMBLY SCAN of its own assembly -- never a compile-time
            // reference to a specific migration class or the Migrations
            // namespace, so Program.cs compiles standalone even before any
            // [Migration] class has been rendered (an empty scan is valid).
            // The migration adapter renders the [Migration] classes
            // into Migrations/BookDb/ over time; this
            // runtime scan finds them.
            var bookDbMigrationConnectionString =
                BookDbConnectionOptions.BuildConnectionString(builder.Configuration);
            rb.AddPostgres()
                .WithGlobalConnectionString(bookDbMigrationConnectionString)
                .ScanIn(typeof(Program).Assembly).For.Migrations();
        })
        .AddLogging(lb => lb.AddFluentMigratorConsole());
    return builder.Build().Services;
}

