static async Task<int> RunReadinessAsync()
{
    using var scope = BuildRuntimeServiceProvider().CreateScope();
    var configuration = scope.ServiceProvider.GetRequiredService<IConfiguration>();
    var report = await RuntimeReadiness.CheckAsync(configuration);
    foreach (var item in report.Items)
    {
        Console.WriteLine($"{item.Kind}\t{item.LogicalName}\t{item.RenderedName}\t{item.Status}");
    }
    return report.Ok ? 0 : 1;
}


